def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main_part, pre_part = core.split('-', 1)
        else:
            main_part, pre_part = core, None

        major, minor, patch = (int(x) for x in main_part.split('.'))

        if pre_part is None:
            has_pre = 1  # no prerelease sorts after
            pre_ids = []
        else:
            has_pre = 0  # has prerelease sorts before
            pre_ids = pre_part.split('.')

        pre_key = []
        for ident in pre_ids:
            if ident.isdigit():
                pre_key.append((0, int(ident)))
            else:
                pre_key.append((1, ident))

        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

